CREATE OR REPLACE FUNCTION public.pm_can_read_incoming_dates(_project uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$
 SELECT auth.uid() IS NOT NULL AND EXISTS(SELECT 1 FROM public.pm_projects WHERE id=_project) AND CASE WHEN public.pm_project_access_cutover_active() THEN public.pm_project_area_proposed(_project,'financials',auth.uid()) ELSE (public.can_edit_project_payment_dates(_project) OR (public.is_psa_staff() AND (public.has_module_permission(auth.uid(),'projects.view_financials','all') OR (public.has_module_permission(auth.uid(),'projects.view_financials','assigned') AND public.pm_has_assigned_access(auth.uid(),_project))))) END
$$;
CREATE FUNCTION public.pm_phase_a_expense_read(_expense uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.pm_expenses e WHERE e.id=_expense AND (NOT public.pm_project_access_cutover_active() OR public.pm_project_area_proposed(e.project_id,'expenses',auth.uid()))) $$;
REVOKE ALL ON FUNCTION public.pm_phase_a_expense_read(uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.pm_phase_a_expense_read(uuid) TO authenticated,service_role;
CREATE POLICY phase_a_area_grant ON public.pm_invoices FOR SELECT TO authenticated USING(public.pm_project_access_cutover_active() AND public.pm_project_area_proposed(project_id,'financials',auth.uid()));
CREATE POLICY phase_a_area_grant ON public.pm_invoice_items FOR SELECT TO authenticated USING(public.pm_project_access_cutover_active() AND EXISTS(SELECT 1 FROM public.pm_invoices i WHERE i.id=invoice_id));
CREATE POLICY phase_a_area_grant ON public.pm_payment_schedule_items FOR SELECT TO authenticated USING(public.pm_project_access_cutover_active() AND public.pm_project_area_proposed(project_id,CASE WHEN direction='inflow' THEN 'financials' ELSE 'supplier_fees' END,auth.uid()));
CREATE POLICY phase_a_area_grant ON public.pm_project_contract_baseline FOR SELECT TO authenticated USING(public.pm_project_access_cutover_active() AND public.pm_project_area_proposed(project_id,'financials',auth.uid()));
CREATE POLICY phase_a_area_grant ON public.pm_project_contract_baseline_payments FOR SELECT TO authenticated USING(public.pm_project_access_cutover_active() AND EXISTS(SELECT 1 FROM public.pm_project_contract_baseline b WHERE b.id=baseline_id));
CREATE POLICY phase_a_area_grant ON public.pm_project_contract_baseline_stages FOR SELECT TO authenticated USING(public.pm_project_access_cutover_active() AND EXISTS(SELECT 1 FROM public.pm_project_contract_baseline b WHERE b.id=baseline_id));
CREATE POLICY phase_a_area_grant ON public.pm_stage_supplier_costs FOR SELECT TO authenticated USING(public.pm_project_access_cutover_active() AND public.pm_project_area_proposed(project_id,'supplier_fees',auth.uid()));
ALTER POLICY phase_a_expense_gate ON public.pm_expenses USING(public.pm_phase_a_area_gate(project_id,'expenses'));
CREATE POLICY phase_a_area_grant ON public.pm_expenses FOR SELECT TO authenticated USING(public.pm_project_access_cutover_active() AND public.pm_project_area_proposed(project_id,'expenses',auth.uid()));
ALTER POLICY pe_flow_read_boundary ON public.pm_expenses USING(CASE WHEN public.pm_project_access_cutover_active() THEN public.pm_project_area_proposed(project_id,'expenses',auth.uid()) ELSE ((workflow_version <> 2) OR (public.is_psa_staff() AND ((submitted_by=auth.uid()) OR public.pe_project_lead(project_id) OR public.pe_finance_access(entity_id)))) END);
CREATE POLICY phase_a_area_gate ON public.pm_materials AS RESTRICTIVE FOR SELECT TO authenticated USING(public.pm_phase_a_area_gate(project_id,'supplier_fees'));
CREATE POLICY phase_a_area_grant ON public.pm_materials FOR SELECT TO authenticated USING(public.pm_project_access_cutover_active() AND public.pm_project_area_proposed(project_id,'supplier_fees',auth.uid()));
CREATE POLICY phase_a_area_gate ON public.pm_project_commercial_baselines AS RESTRICTIVE FOR SELECT TO authenticated USING(public.pm_phase_a_area_gate(project_id,'financials'));
CREATE POLICY phase_a_area_grant ON public.pm_project_commercial_baselines FOR SELECT TO authenticated USING(public.pm_project_access_cutover_active() AND public.pm_project_area_proposed(project_id,'financials',auth.uid()));
CREATE POLICY phase_a_area_gate ON public.pm_stage_commercial_baselines AS RESTRICTIVE FOR SELECT TO authenticated USING(public.pm_phase_a_area_gate(project_id,'budget_cost'));
CREATE POLICY phase_a_area_grant ON public.pm_stage_commercial_baselines FOR SELECT TO authenticated USING(public.pm_project_access_cutover_active() AND public.pm_project_area_proposed(project_id,'budget_cost',auth.uid()));
CREATE POLICY phase_a_expense_child_gate ON public.project_expense_events AS RESTRICTIVE FOR SELECT TO authenticated USING(NOT public.pm_project_access_cutover_active() OR public.pm_phase_a_expense_read(expense_id));
CREATE POLICY phase_a_expense_child_gate ON public.project_expense_invoice_allocations AS RESTRICTIVE FOR SELECT TO authenticated USING(NOT public.pm_project_access_cutover_active() OR public.pm_phase_a_expense_read(expense_id));
CREATE POLICY phase_a_expense_child_gate ON public.project_expense_receipt_allocations AS RESTRICTIVE FOR SELECT TO authenticated USING(NOT public.pm_project_access_cutover_active() OR EXISTS(SELECT 1 FROM public.project_expense_invoice_allocations a WHERE a.id=invoice_allocation_id));
CREATE POLICY phase_a_expense_child_gate ON public.project_expense_credit_allocations AS RESTRICTIVE FOR SELECT TO authenticated USING(NOT public.pm_project_access_cutover_active() OR EXISTS(SELECT 1 FROM public.project_expense_invoice_allocations a WHERE a.id=invoice_allocation_id));
COMMENT ON FUNCTION public.pm_can_read_incoming_dates(uuid) IS 'Legacy readers remain effective only while separately approved cutover is OFF; ON uses Financials area capability. No Finance write privilege granted.';